# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FIRINDA, BAKKALDA VE MANAVDA: SEBZE, MEYVE VE UNLU MAMULLER</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Fırın ve Bakkal (فِي الْمَخْبَزِ وَالْبَقَّالِ)</text>\n  <text x="42" y="100" font-size="11.5" fill="#334155">• خُبْزٌ (Hubzun): Ekmek</text>\n  <text x="42" y="124" font-size="11.5" fill="#334155">• كَعْكٌ (Ka\'kun): Simit / Çörek</text>\n  <text x="42" y="148" font-size="11.5" fill="#334155">• جُبْنٌ (Cübnün): Peynir</text>\n  <text x="42" y="172" font-size="11.5" fill="#334155">• زَيْتُونٌ (Zeytûnun): Zeytin</text>\n  <text x="42" y="196" font-size="11.5" fill="#334155">• حَلِيبٌ / بَيْضٌ: Süt / Yumurta</text>\n  <text x="130" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">أُرِيدُ خُبْزًا طَازَجًا (Taze ekmek istiyorum)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Sebzeler (الْخَضْرَاوَاتُ)</text>\n  <text x="262" y="100" font-size="11.5" fill="#334155">• طَمَاطِمُ (Tamâtimu): Domates</text>\n  <text x="262" y="124" font-size="11.5" fill="#334155">• خِيَارٌ (Hiyârun): Salatalık</text>\n  <text x="262" y="148" font-size="11.5" fill="#334155">• بَطَاطِسُ (Batâtisu): Patates</text>\n  <text x="262" y="172" font-size="11.5" fill="#334155">• بَصَلٌ (Basalun): Soğan</text>\n  <text x="262" y="196" font-size="11.5" fill="#334155">• بَاذِنْجَانٌ / فُلْفُلٌ: Patlıcan / Biber</text>\n  <text x="350" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">كِيلُو مِنَ الطَّمَاطِمِ (Bir kilo domates)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">3. Meyveler (الْفَوَاكِهُ)</text>\n  <text x="482" y="100" font-size="11.5" fill="#334155">• تُفَّاحٌ (Tüffâhun): Elma</text>\n  <text x="482" y="124" font-size="11.5" fill="#334155">• بُرْتُقَالٌ (Burtukâlun): Portakal</text>\n  <text x="482" y="148" font-size="11.5" fill="#334155">• مَوْزٌ (Mevzun): Muz</text>\n  <text x="482" y="172" font-size="11.5" fill="#334155">• عِنَبٌ (İnebun): Üzüm</text>\n  <text x="482" y="196" font-size="11.5" fill="#334155">• بَطِّيخٌ / إِجَّاصٌ: Karpuz / Armut</text>\n  <text x="570" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">كِيلُو مِنَ التُّفَّاحِ (Bir kilo elma)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARTI / ÖLÇÜ İFADELERİ (كِيلُو مِنْ...) VE TERCİH KALIBI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tartı ve Ölçü Kalıpları (الْوَزْنُ وَالْكَيْلُ)</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• كِيلُو مِنَ التُّفَّاحِ (Bir kilo elma)</text>\n  <text x="44" y="124" font-size="11.5" fill="#334155">• نِصْفُ كِيلُو مِنَ الْجُبْنِ (Yarım kilo peynir)</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">• رُبْعُ كِيلُو مِنَ الزَّيْتُونِ (Çeyrek kilo zeytin)</text>\n  <text x="44" y="172" font-size="11.5" fill="#334155">• عُلْبَةٌ مِنَ الْحَلِيبِ (Bir kutu süt)</text>\n  <text x="44" y="196" font-size="11.5" fill="#334155">• كِيسٌ مِنَ الدَّقِيقِ (Bir paket / torba un)</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">أَنَا بِحَاجَةٍ إِلَى كِيلُو مِنَ الْبَطَاطِسِ</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Soru, Tercih ve Bağlaç Kalıpları</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• بِكَمْ كِيلُو الطَّمَاطِمِ؟ (Domatesin kilosu kaça?)</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">• هَلْ عِنْدَكَ خُبْزٌ طَازَجٌ؟ (Taze ekmeğin var mı?)</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• أَتُفَضِّلُ التُّفَّاحَ أَمِ الْمَوْزَ؟ (Elmayı mı muzu mu?)</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">• أُفَضِّلُ التُّفَّاحَ وَالْبُرْتُقَالَ. (Elma ve portakalı tercih ederim.)</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">• كَمِ الْمَجْمُوعُ يَا عَمِّي؟ (Toplam ne kadar amcacığım?)</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Bağlaçlar: وَ (ve) · أَوْ (veya) · أَمْ (yoksa) · ثُمَّ (sonra)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PAZARDA / MANAVDA DİYALOG VE ÖLÇÜ-TARTI AHLAKI</text>\n  <rect x="28" y="48" width="330" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="193" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Halk Pazarında Diyalog (فِي السُّوقِ الشَّعْبِيِّ)</text>\n  <text x="42" y="98" font-size="11" font-weight="bold" fill="#1e40af">الْبَائِعُ: أَهْلًا وَسَهْلًا، مَاذَا تُرِيدُ؟</text>\n  <text x="42" y="114" font-size="10.5" fill="#475569">(Satıcı: Hoş geldiniz, ne istersiniz?)</text>\n  <text x="42" y="136" font-size="11" font-weight="bold" fill="#166534">الْمُشْتَرِي: أُرِيدُ كِيلُو مِنَ الطَّمَاطِمِ، ثُمَّ نِصْفَ كِيلُو مِنَ الْخِيَارِ.</text>\n  <text x="42" y="152" font-size="10.5" fill="#475569">(Müşteri: Bir kilo domates, sonra yarım kilo salatalık istiyorum.)</text>\n  <text x="42" y="174" font-size="11" font-weight="bold" fill="#1e40af">الْبَائِعُ: تَفَضَّلْ، الْمَجْمُوعُ ثَلَاثَ عَشْرَةَ لِيرَةً.</text>\n  <text x="42" y="190" font-size="10.5" fill="#475569">(Satıcı: Buyurun, toplam 13 liradır.)</text>\n  <text x="42" y="212" font-size="11" font-weight="bold" fill="#166534">الْمُشْتَرِي: شُكْرًا جَزِيلًا، بَارَكَ اللّٰهُ فِيكَ.</text>\n  <text x="42" y="228" font-size="10.5" fill="#475569">(Müşteri: Çok teşekkür ederim, Allah bereket versin.)</text>\n  <rect x="374" y="48" width="298" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="523" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ölçü ve Tartı Ahlakı İlkeleri</text>\n  <text x="388" y="102" font-size="11.5" font-weight="bold" fill="#92400e">• اِنْتَبِهْ لِلْكَيْلِ وَالْمِيزَانِ</text>\n  <text x="396" y="120" font-size="11" fill="#334155">Ölçüye ve tartıya dikkat et! (Eksik tartma)</text>\n  <text x="388" y="148" font-size="11.5" font-weight="bold" fill="#92400e">• اللّٰهُ لَا يُحِبُّ الْمُطَفِّفِينَ</text>\n  <text x="396" y="166" font-size="11" fill="#334155">Allah ölçü ve tartıda hile yapanları sevmez.</text>\n  <text x="388" y="194" font-size="11.5" font-weight="bold" fill="#92400e">• الْكَاسِبُ حَبِيبُ اللّٰهِ</text>\n  <text x="396" y="212" font-size="11" fill="#334155">Helalinden çalışan ve kazanan Allah\'ın dostudur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
